// Classic Java I/O Decorator Chain Example
import java.io.*;

public class DecoratorDemo {
    public static void main(String[] args) throws IOException {
        // Base component stream reading raw bytes from a file
        InputStream fileStream = new FileInputStream("data.bin");

        // First decorator: adds internal memory buffering for performance
        InputStream bufferedStream = new BufferedInputStream(fileStream);

        // Second decorator: adds data decompression capabilities
        InputStream compressedStream = new java.util.zip.GZIPInputStream(bufferedStream);

        // Client interacts uniformly through the base InputStream interface
        int data = compressedStream.read();
        compressedStream.close();
    }
}
